import pyAether as pyScript

def vary_dbclosecv(cvs):
    closed = []
    for cv in cvs:
        closed.append(pyScript.dbCloseCV(cv))
    return closed

import pyAether as pyScript

def vary_dbnewcv(specs):
    cvs = []
    for lib, cell, view, vtype in specs:
        cv = pyScript.dbNewCV(lib=lib, cell=cell, view=view, viewType=vtype)
        if cv is not None:
            cvs.append(cv)
    return cvs

import pyAether as pyScript

def find_and_open(lib_name, cell, view="layout"):
    libs = pyScript.dbGetAllLibs()
    names = [str(l) for l in libs]
    if lib_name not in names:
        return None
    return pyScript.dbOpenCV(lib=lib_name, cell=cell, view=view, mode="r")
